mapper.select:
select r.record_id, r.exam_id, r.paper_id, r.course_id, r.student_id, r.attempt_no, r.start_time, r.submit_time, r.duration_seconds, r.exam_status as record_status, r.objective_score, r.subjective_score, r.total_score, r.pass_flag as result_status, r.checked_flag, u.user_name as student_user_name, u.nick_name as student_name from edu_exam_record r left join sys_user u on r.student_id = u.user_id
r.exam_id = #{examId}
and (u.user_name like concat('%', #{studentKeyword}, '%') or u.nick_name like concat('%', #{studentKeyword}, '%'))
and r.exam_status = #{recordStatus}
and r.pass_flag = #{resultStatus}
order by r.record_id desc
